#!/usr/bin/env python3
"""Build three text editions and a compiled paper from bound execution evidence."""
import argparse
import hashlib
import html
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile

ROOT=Path(__file__).resolve().parents[1]
MICRO=1_000_000
REFERENCE_DOCX_SHA256='8916ec49efa7ed5c74d4a45e83731c88df108da6ea83977dfef654709457bdd2'
REFERENCE_TEXT_SHA256='03dbfd4a509407bbcc40c8485e4a98f12b0d919cce737fd0d7d4126027ced062'


def sha(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def load(path): return json.loads(Path(path).read_text())
def money(value): return ('-' if value<0 else '')+f'${abs(value)/MICRO:,.2f}'
def pct(value): return f'{100*value:.1f}%'
def num(value): return f'{value:,}'
def arm_prices(value): return 'NoBid' if value['selected_price_policy'] is None else money(value['first_price'])+' / '+money(value['repeat_price'])
def relative(path):
    try: return str(Path(path).resolve().relative_to(ROOT))
    except ValueError: raise ValueError('Paper inputs must be inside the repository')
def tex(value):
    trans={'\\':r'\textbackslash{}','&':r'\&','%':r'\%','$':r'\$','#':r'\#','_':r'\_\allowbreak{}','{':r'\{','}':r'\}','~':r'\textasciitilde{}','^':r'\textasciicircum{}'}
    escaped=''.join(trans.get(c,c) for c in str(value))
    return re.sub(r'[0-9a-f]{32,64}',lambda m:r'\texttt{'+r'\allowbreak{}'.join(m.group()[i:i+8] for i in range(0,len(m.group()),8))+'}',escaped)
def write(path,text): Path(path).write_text(text,encoding='utf-8')


def editions(title,subtitle,nodes):
    md=[f'# {title}',subtitle,'']; ht=[f'<h1>{html.escape(title)}</h1>',f'<p class="subtitle">{html.escape(subtitle)}</p>']; lt=[]
    for node in nodes:
        kind=node[0]
        if kind=='h':
            text=node[1];md+=['## '+text,''];ht+=['<h2>'+html.escape(text)+'</h2>'];lt += ['\\section*{'+tex(text)+'}']
        elif kind=='p':
            text=node[1];md += [text,''];ht += ['<p>'+html.escape(text)+'</p>'];lt += [tex(text)+'\n']
        elif kind=='table':
            headers,rows=node[1:];md += ['| '+' | '.join(headers)+' |','| '+' | '.join('---' for _ in headers)+' |']+['| '+' | '.join(str(x).replace('|','/') for x in row)+' |' for row in rows]+['']
            ht += ['<div class="table"><table><thead><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>']
            cols=len(headers); widths=[.28]+[.60/(cols-1)]*(cols-1) if cols>1 else [.88]
            lt += ['\\begin{longtable}{'+''.join(r'>{\raggedright\arraybackslash}p{'+f'{w:.3f}\\linewidth'+'}' for w in widths)+'}','\\toprule',' & '.join('\\textbf{'+tex(h)+'}' for h in headers)+r'\\','\\midrule','\\endhead']
            lt += [' & '.join(tex(x) for x in row)+r'\\' for row in rows]+['\\bottomrule','\\end{longtable}']
        elif kind=='code':
            text=node[1];md+=['```text',text,'```',''];ht+=['<pre>'+html.escape(text)+'</pre>'];lt+=['\\begin{Verbatim}[fontsize=\\scriptsize,breaklines=true]',text,'\\end{Verbatim}']
        elif kind=='links':
            rows=node[1];md += [f'- [{label}]({url})' for label,url in rows]+[''];ht += ['<ul>'+''.join('<li><a href="'+html.escape(url,quote=True)+'">'+html.escape(label)+'</a></li>' for label,url in rows)+'</ul>'];lt += ['\\begin{itemize}']+['\\item \\href{'+url+'}{'+tex(label)+'}' for label,url in rows]+['\\end{itemize}']
        else: raise ValueError(kind)
    return '\n'.join(md),'\n'.join(ht),'\n'.join(lt)


def build(args):
    results=Path(args.results).resolve();policy_path=Path(args.policy).resolve();manifest_path=Path(args.manifest).resolve();out=Path(args.output).resolve()
    for p in (results,policy_path,manifest_path,out): relative(p)
    r,p,m=load(results),load(policy_path),load(manifest_path)
    if r.get('scope')!='SIMULATED' or r.get('schema')!='agi-alpha/commercial010-campaign/v2': raise ValueError('Expected executed scoped commercial010 campaign results')
    if r['policy_file_sha256']!=sha(policy_path) or r['cohort_file_sha256']!=sha(manifest_path): raise ValueError('RESULT_INPUT_IDENTITY_MISMATCH')
    if m['accepted_count']!=sum(j['accepted'] for j in m['jobs']): raise ValueError('COHORT_SUMMARY_MISMATCH')
    for job in m['jobs']:
        for field in ('input','artifact','receipt'):
            bound=ROOT/job[field];relative(bound)
            if sha(bound)!=job[field+'_sha256']: raise ValueError('COHORT_ARTIFACT_CHANGED: '+job[field])
    nodes=[]
    def h(s):nodes.append(('h',s))
    def para(s):nodes.append(('p',s))
    def table(headers,rows):nodes.append(('table',headers,rows))
    def code(s):nodes.append(('code',s))
    rows_count=sum(len(load(ROOT/j['input'])[field]) for j in m['jobs'] for field in ('invoices','payments'))
    wall=sum(a.get('wall_seconds',0) for a in m['attempts']);cpu=sum(a.get('cpu_seconds',0) for a in m['attempts'])
    region=r['qualification_region'];worlds=r['worlds'];nconfirm=sum(sum(w['runs'] for w in arm['worlds'].values()) for arm in r['arms'].values());prices=[money(p['human_benchmark']*x//10000) for x in p['price_multipliers_bps']]
    best_arm=r['arms']['strategic_autonomous_onboarding']
    first_quote='NoBid' if best_arm['selected_price_policy'] is None else money(best_arm['first_price'])
    repeat_quote='NoBid' if best_arm['selected_price_policy'] is None else money(best_arm['repeat_price'])
    title='A fixed-capability autonomous commercial loop under explicit simulated market conditions'
    subtitle='AGI ALPHA Invention Flywheel Lab | Executed synthetic reconciliation, strategic buyers and audited earned-funded repetition | 30 October 2026'
    h('Abstract')
    para(f'We implemented and executed a bounded receivables-reconciliation service, a strategic repeated-market environment and an event-level financial auditor. The cohort supplied {num(rows_count)} authored synthetic records across {len(m["jobs"])} orders: {m["accepted_count"]} deliveries passed a separately implemented checker and {m["rejected_count"]} orders were rejected. Buyers, rival providers, free/conventional self-service and a supplier heuristic affect transactions; all customers, orders and payments are explicitly simulated. Across {nconfirm} prespecified four-arm seeded confirmation runs, the joint strategic-pricing/autonomous-onboarding arm offered {first_quote} first-order and {repeat_quote} repeat-order prices. In the declared qualification region, {region["go_runs"]}/{region["runs"]} runs supported repeated profitable delivery and continuation from prior unrestricted simulated earnings. This is a conditional model result over actually executed synthetic service artifacts, not observed commerce, population-level demand validation, recursive capability improvement or Blue Sky enablement.')
    h('1. Independent success definitions and evidence scope')
    table(['Conclusion','Machine verdict','Evidence scope'],[[k.replace('_',' '),v['verdict'],v['scope']] for k,v in r['verdicts'].items()])
    para('Fixed-capability commercial success is independent of recursive invention. This campaign does not join the five conclusions with a global AND. The observed lane remains closed because no actual customer collection or exact provider bill was obtained. A successful simulated loop remains simulated in every downstream balance and investment; neither a simulation flag nor missing host billing automatically sets qualified simulated earnings to zero.')
    para('The later independent-commercial clarification in the supplied reference-v6 was read. Only its DOCX and extracted-text hashes are recorded here; its full contents are not published. Existing invention mechanisms, failed experiments and PR12-14 evidence are preserved separately. This ordinary service is neither relabeled an autonomous invention nor used to infer a fresh inherited-capability advantage.')
    h('2. Executed service production and acceptance')
    para('A bounded screen compared researched articles, tested software patches and receivables reconciliation. Reconciliation was selected for exact independently checkable outcomes. Orders contain USD integer-cent invoice and bank-payment records, customer identities, references and an explicit completeness obligation. Delivery produces a row-level JSON reconciliation and exception CSV. Referenced bundles and split payments match only at exact cents and consistent customer identity. Unreferenced payments require unique corresponding invoice and payment candidates. Overlapping exact reference groups remain quarantined.')
    para(f'The larger executed cohort contains {len(m["jobs"])} orders of 1,000 total source records each. Namespaced blocks synthesize diverse reference, split, bundled, unique-amount, partial, ambiguous and conflicting-reference patterns. Original completeness contracts are retained: valid exception schedules can be accepted only when the order allows unresolved findings; strict-completeness ambiguity is rejected. Unsupported CAD and a negative reversal are rejected at input validation; the strict ambiguous order receives a reconciliation that fails its completeness obligation. Thus 19,000 supplied records must not be relabeled 19,000 successfully reconciled records. The original smaller cohort and its exact source snapshots remain available; small source examples are not used to justify a four-hour human service estimate.')
    para('All inputs are authored public synthetic workloads. They are not client records or deidentified real books. Generation families and reused seed sets are disclosed; the larger execution is engineering replication, not a fresh population holdout. The unsafe-first-match output is a supplied adversarial counterexample, not a naturally observed frontier-model error rate. Its balanced arithmetic conceals an arbitrary ambiguous allocation, which the checker rejects. No tax filing, professional attestation, record modification, fraud certification or money movement is within this service contract.')
    para(f'The recorded production and checking CPU time for the cohort was {cpu:.6f} seconds, with {wall:.6f} seconds wall time. These measurements exclude agent inference, code construction, orchestration and wider campaign work. They are not complete costs and are never converted into human work hours. Separate builder and checker roles share the execution host and model family; this is procedural separation, not external certification. Exact routed model/version, settings, token receipts and host billing were not exposed.')
    onboarding_path=ROOT/'campaign/commercial-010/onboarding/executed-001/RESULT.json'
    if onboarding_path.exists():
        onboarding=load(onboarding_path)
        para('The added autonomous onboarding workflow creates clearly synthetic CSV exports from the frozen source records, then actually parses explicit contract metadata and invoice/payment tables into validated canonical order JSON. It supports the declared known CSV schema, exact headers, quoting/BOM, integer-cent units and explicit currency/reference checks. It does not claim an arbitrary financial-system integration or an actual customer export.')
        para('Across '+str(onboarding['orders'])+' orders, '+str(onboarding['onboarding_accepted'])+' imports reproduced the exact canonical source bytes, '+str(onboarding['input_rejected'])+' inputs were rejected and '+str(onboarding['independent_service_accepted'])+' passed independent service acceptance. Total measured import/preparation plus production/requalification work was '+str(round(onboarding['agent_import_cpu_seconds'],6))+' CPU seconds and '+str(round(onboarding['agent_import_wall_seconds'],6))+' wall seconds. These machine timings do not establish a monetary bill or zero customer attention. A malformed duplicate-header probe was rejected.')
        table(['Item / payer','Evidence','Timing / uncertainty'],[['Agent onboarding / seller','Actual CSV preparation, parsing and checks; machine work timed','First-customer setup budget '+money(p['agent_onboarding_autonomous_interval'][0])+'-'+money(p['agent_onboarding_autonomous_interval'][1])+' is conditional, not exact billing; repeated imports still cost resources'],['Customer attention / buyer','Approval, switching, export and integration burden unobserved','Separate $0-$50 utility-friction range; not seller staff wages and not proved zero'],['External fees / named payer','No new paid external transaction in actual workflow','Default zero only for declared no-paid-provider case; stress when applicable']])
    h('3. Strategic actors, payoffs and timing')
    para(f'The horizon is {p["cycles"]} cycles with {p["jobs_per_cycle"]} candidate deliveries per cycle, a finite cohort and bounded buyer budgets. No output can be sold twice within a run. Buyer participation is chosen from our service, a competent human-delivered alternative, an adapting rival, free/conventional self-service and no purchase. Buyers have heterogeneous latent values; arrivals, trust, switching costs, payment incentives and future reputation affect repeat choices. Rival decisions use noisy value proxies. Parameters are transparent conditional assumptions rather than observed willingness to pay. The 0.99 and 0.97 utility coefficients and trust levels are assumed ex ante reliability/value weights, not measured comparative accuracy estimates. Both completed-service routes are assessed against the same declared functional obligations; this experiment does not establish inferior human acceptance quality.')
    code('U_own = own_trust * 0.99 * value - own_price - onboarding + fast_delivery_premium\nU_rival = rival_trust * rival_quality * value - rival_price - rival_switching + fast_delivery_premium\nU_human = max(0, 0.97 * value - human_benchmark)\nU_self = 0.99 * self_service_trust * value - self_service_cost + fast_delivery_premium\nparticipate = arrival AND affordable AND U_own >= max(0, U_rival, U_human, U_self)')
    para('The competing provider searches a 30-point price/quality grid to maximize (price minus conditional unit cost) times estimated customer count. A reported zero residual verifies only maximization over that grid against noisy information. It is not a Nash equilibrium certificate, a continuous best response or a proof that no strategic deviation exists. The supplier uses a bounded scarcity pricing heuristic: the exogenous world term is multiplied by one plus 5% times batch utilization. Supplier terms and buyer preferences are structural assumptions; random seeds describe only variation within those assumptions.')
    para('Before each batch, the native exchange checks funding and commitments; actual deterministic service production and independent checking then run again on the selected source-bound orders. This sequencing prevents a claim that new earnings financed earlier qualification work. The actual host resource bill remains unknown: earned funds and resource payments in this demonstration are simulated. Provider investment and batch production precede buyer choice, so unsold inventory still costs resources. For a buyer who participates, consent, customer escrow funding and preparation precede release or refund; this is not order-specific consent before production. Delayed settlement, the contractual deadline, modeled revision charges, disputes, reputation updates, finite budgets and unsold work can prevent collection and repeat success. Market revision events are stochastic cost/risk draws, not separately executed corrected service artifacts; the actual artifact correction/rejection evidence is retained in the service cohort.')
    table(['World','Own / rival trust','Buyer friction original / corrected USD','Fast premium USD','Self-service USD / trust'],[[w['id'],str(w['trust'])+' / '+str(w['rival_trust']),str(w.get('original_switching',w['switching']))+' / '+str(w['switching']),str(w.get('delivery_premium',0)),str(w.get('self_service_cost','absent'))+' / '+str(w.get('self_service_trust','absent'))] for w in p['worlds']])
    para('The fast-delivery premium and lower onboarding assumptions define the targeted segment, not a measured discovery about actual buyers. The same premium is given to rival digital delivery and self-service. Fast conventional or self-service alternatives can therefore defeat the offer. The free-code alternative has zero software license price, while its declared user time/operating cost and execution trust remain uncertain model assumptions. Rival optimization uses own, human, self-service and abstention utilities with public switching assumptions, but private budgets and exact values remain uncertain. Its grid residual is conditional on that approximate information model.')
    h('4. Human comparison and premium pricing')
    para(f'The human benchmark is {money(p["human_benchmark"])} for a four-hour manual-service scenario. BLS bookkeeping wages are loaded once using a published total-compensation-to-wages ratio; the rounded loaded rate is approximately $34.75 per hour. The four hours comprise assumed 0.5 hour first-customer human onboarding/setup plus 3.5 hours recurring human preparation, reconciliation, verification, corrections, delivery and support. The repeat-order loaded-labor benchmark is therefore $121.625 rather than adding onboarding again to $139. All human-side stages remain human work at human compensation. The task times are unmeasured scenario assumptions, not performance measurements against an accountant or strong import/reconciliation tools. The policy interval is {money(p["human_benchmark_interval"][0])} to {money(p["human_benchmark_interval"][1])}. It is an assumed four-hour loaded-labor comparator covering the declared scope and obligations, with zero incremental nonlabor expense. No matched completed human workflow was measured; further enterprise costs are not invented or double counted. Fast competent conventional tools can reduce human time and erode the price anchor.')
    para(f'The initial offer applies a {p["initial_discount_bps"]/100:.1f}% declared discount to the human benchmark. Exploration tests {", ".join(prices)} and evaluates the joint effects of price, discount and win probability on expected collected complete-cost profit and sustainable cash. The objective is neither maximum win rate nor the highest advertised price; the feasible premium-price grid and information assumptions bound any optimum claim. The selected first/repeat prices and their price-win-profit curves are reported below; adaptive candidate policies may set different multipliers on the first and repeat human anchors. Low AI cost is retained as potential margin rather than used as a cost-plus selling-price rule. A premium list price without buyer participation cannot qualify.')
    para('The human operation performs human work at human speed with loaded compensation. Agent-side research, production, verification, correction, acquisition, support, development and maintenance are machine workloads; no default human reviewer, salesperson or developer wage is inserted. No human performed per-job preparation, checking, correction, delivery or simulated transaction execution. The owner supplied the mandate and steering clarifications; these are disclosed inputs rather than hidden service staffing. No timed human service intervention was observed. Conventional and AI-native alternatives constrain willingness to pay; their technical parity does not automatically invalidate profitable autonomous service economics versus the human comparator.')
    table(['Human stage','First-order hours','Repeat-order hours'],[[stage,str(hours),'0' if stage=='onboarding' else str(hours)] for stage,hours in p['human_stages_hours_first'].items()]+[['Total',str(sum(p['human_stages_hours_first'].values())),str(p['human_repeat_hours'])]])
    para('Original agent onboarding is contained within the recurring resource envelope; its separate zero line does not assert a free operation. The corrected arm adds '+money(p['agent_onboarding_autonomous'])+' of explicitly conditional first-customer agent setup expense, with interval '+money(p['agent_onboarding_autonomous_interval'][0])+' to '+money(p['agent_onboarding_autonomous_interval'][1])+'. Customer friction is a separate buyer utility term; external onboarding fee '+money(p['external_onboarding_fee'])+' is separate again. Setup is charged once when first consented technical acceptance occurs and remains completed after a refund; future orders are not guaranteed to amortize it.')
    para("The owner's four article, analysis, software-patch and accounting examples remain separate illustrative comparison fixtures. Their hypothetical budgets and lower reference selling prices are not measured service costs, current willingness to pay or the default premium-pricing rule. In particular, the accounting illustration is not the observed cost of this 1,000-record service. The present four-hour/$139 human scenario and conditional machine-resource envelopes are explicitly distinct assumptions.")
    h('5. Complete modeled costs and financial conservation')
    table(['Quantity','Declared value / treatment'],[['Opening simulated liquidity',money(p['opening'])+'; seed is not earnings'],['Restricted working capital',money(p['working'])],['Whole-campaign setup cost',money(p['setup_cost'])+'; interval '+money(p['setup_cost_interval'][0])+' to '+money(p['setup_cost_interval'][1])],['Cost per cohort unit',money(p['per_job_cost'])+'; interval '+money(p['per_job_cost_interval'][0])+' to '+money(p['per_job_cost_interval'][1])],['Acquisition new / repeat',money(p['acquisition_new'])+' / '+money(p['acquisition_repeat'])],['Support allowance per scheduled delivery',money(p['support_per_sale'])],['Payment charge',f'{p["payment_bps"]/100:.1f}% plus '+money(p['payment_fixed'])],['Tax provision',f'{p["tax_bps"]/100:.1f}% conditional scenario; not a statement of applicable tax law']])
    para('Setup includes campaign development, failed search, integration, acquisition design and maintenance. Per-unit envelopes include agent inference, tools, computation, storage, production, verification, corrections, rejected and unsold work, delivery and support obligations. Setup is charged in every arm, including NoBid. A completed horizon allocates all cohort and additional failed-attempt cost units through scheduled production batches, including unsold work. NoBid or an early stop avoids later unperformed batches; it does not erase incurred qualification/setup costs. The support allowance is charged per scheduled delivery, including unsold output, rather than only per collected sale. Source-exact token receipts are unavailable; the cost intervals are explicit conditional resource envelopes, not fabricated measured bills. A favorable result at the chosen point does not by itself prove profitability throughout the full declared interval.')
    para('The ledger adapts the existing native ProtectedExchange instead of redefining earned funds. The commerce006 loader checks the four vendor source hashes before import, and the paper manifest binds that loader, contracts, exchange implementation and preserved Apache-2.0 license. No other foundation repository is modified by this campaign. Monetary state uses integer simulated microUSD. The auditor reconstructs events and verifies source-bound cohort artifacts rather than accepting stored summary fields. Revenue, collection, refund, expenses, principal reserves, restricted custody, seed liquidity and available earned funds remain distinct; source order states record unsettled payment obligations. Commitment requires cash first; seed, deposits or restricted reserves cannot become earned capital. The full settled principal reserve and fixed per-order liability remain reserved through the modeled horizon, so accounting profitability and investment liquidity can differ.')
    para('Further acquisition and delivery capacity are funded only when the native unrestricted-earned gate admits the commitment and obligations remain covered. No capability-improved successor is required. The policy retains cash when incremental activity lacks support; capture, retained available earnings and actual simulated continuation expenditure are reported separately. Invention is an optional additional use of earnings, not a hidden condition for commercial qualification.')
    h('6. Four-arm pricing, onboarding and common-draw confirmation')
    para(f'Exploration seeds are {p["exploration_seeds"]}; confirmation seeds are {p["confirmation_seeds"]}. The factorial arms are fixed 95% pricing/original onboarding, fixed 95% pricing/autonomous onboarding, strategic pricing/original onboarding, and both corrections. These are new controlled configurations under common final scenarios; fixed_original is not a rewrite or exact reexecution of the preserved earlier zero-sale experiment. Strategic policies maximize equally weighted exploration mean collected complete-cost profit subject to cash survival and no payable breaches, including NoBid as a cash-preserving alternative. Seller observations contain the declared prior value interval, public history and balances; private realized values, reservation prices and future draws are excluded. Pricing is frozen before confirmation; no target win-rate or perfect-GO gate chooses the price.')
    para('Common random inputs are keyed by seed, cycle, buyer and channel for values, arrivals, noisy rival information, revisions and disputes. This prevents conditional purchases from shifting later random draws between arms. Endogenous purchases, onboarding, trust, prices, balances and investment may diverge. The resulting paired contrasts identify model-intervention effects under the stated policies and assumptions; they are not empirical causal effects of onboarding on actual customers. The revised development history is disclosed, and this finite model comparison makes no population-confidence or statistical-alpha claim.')
    table(['Arm','First / repeat price','Expected complete profit','Paid win / cash survival','Mean repeat / earned cycles'],[[name,arm_prices(v),money(v['qualification_region']['expected_complete_profit']),pct(v['qualification_region']['win_probability'])+' / '+pct(v['qualification_region']['cash_survival_fraction']),f"{v['qualification_region']['mean_repeat_buyers']:.2f} / {v['qualification_region']['mean_earned_funded_cycles']:.2f}"] for name,v in r['arms'].items()])
    table(['Arm','Profit min / median / max','Mean available earned','Mean reinvestment','GO / runs'],[[name,money(v['qualification_region']['profit_min'])+' / '+money(v['qualification_region']['profit_median'])+' / '+money(v['qualification_region']['profit_max']),money(v['qualification_region']['expected_unrestricted_earned']),money(v['qualification_region']['mean_reinvested_earned']),str(v['qualification_region']['go_runs'])+'/'+str(v['qualification_region']['runs'])] for name,v in r['arms'].items()])
    para('Paid win frequency is collected jobs divided by production opportunities, not a guaranteed acceptance probability. All four arms share the same source-bound service quality and rejection rules: 16 qualified artifact contracts from 19 supplied orders. First and repeat price policies are the observed price-distribution support in this game; buyer state determines their mixture. Regional commercial qualification requires positive expected complete profit, all modeled runs surviving with no payable breach, and mean earned-funded cycles and repeat buyers meeting the declared thresholds. Individual run GO counts remain separately reported descriptive outcomes.')
    para('Integer price-policy labels are basis points of the applicable human anchor: 9500 means 95%. Adaptive labels encode first/repeat multipliers; None denotes NoBid rather than a free service. The displayed first/repeat prices describe each policy support, not an empirically observed willingness-to-pay distribution. All USD tables round to cents for display; replay uses exact integer simulated microUSD.')
    for name,selection in r['price_selection']['selections'].items():
        para('Exploration price response for '+name+'; selected policy '+str(selection['selected_multiplier_bps'])+', finite-grid profitable-deviation residual '+money(selection['seller_grid_profitable_deviation_residual'])+'. Zero residual is limited to this candidate grid, information model and sampled conditional prior, not Nash or globally optimal continuous pricing.')
        table(['Price policy','Expected complete profit','Paid win probability','Available cash / survival'],[[str(c['price_multiplier_bps']),money(c['expected_complete_profit']),pct(c['win_probability']),money(c['expected_available_cash'])+' / '+pct(c['cash_survival_fraction'])] for c in selection['candidate_curve']])
    region_ids={w['id'] for w in p['worlds'] if w['qualification_region']}
    contrasts=[]
    for name,contrast in r['paired_contrasts'].items():
        pairs=contrast['pairs'];regional=[x for x in pairs if x['world'] in region_ids];deltas=sorted(x['complete_profit_delta'] for x in pairs)
        contrasts.append([name,money(contrast['mean_complete_profit_delta']),money(sum(x['complete_profit_delta'] for x in regional)/len(regional)),money(deltas[0])+' / '+money(deltas[len(deltas)//2])+' / '+money(deltas[-1]),f"{sum(x['paid_jobs_delta'] for x in pairs)/len(pairs):.2f}"])
    table(['Paired intervention','All-world mean profit delta','Region mean profit delta','Delta min / median / max','Mean paid-job delta'],contrasts)
    para('The fixed-price onboarding contrast most directly isolates the modeled onboarding intervention. Strategic-original and strategic-autonomous arms may select different optimized prices; their contrast is a total reoptimized-policy effect, not a pure same-price onboarding effect. Paired controls preserve the same exogenous scenario inputs and budgets, while treatment-induced expense and transaction outcomes remain allowed to differ.')
    para('The following world-level distributions refer to the combined strategic/autonomous-onboarding arm. A conditional positive qualification does not imply success in every world or realization, and the faster-human, commodity and adverse alternatives remain material constraints.')
    table(['World','GO / runs','Profit min / median / max','Paid jobs','Earned cycles'],[[name,f'{v["go_runs"]}/{v["runs"]}',f'{money(v["profit_min"])} / {money(v["profit_median"])} / {money(v["profit_max"])}',str(v['paid_jobs_range']),str(v['earned_cycles_range'])] for name,v in worlds.items()])
    para(f'The qualification-region aggregate is {region["go_runs"]}/{region["runs"]} GO runs ({pct(region["go_fraction"])}), with modeled profit from {money(region["profit_min"])} to {money(region["profit_max"])} and median {money(region["profit_median"])}. These distributions are conditional on the declared heuristic game and frozen cost point. They do not imply the corresponding frequency of real profitable businesses.')
    run_paths=sorted(results.parent.glob('confirmation/*/*/*/RESULT.json'))
    if not run_paths: run_paths=sorted(results.parent.glob('representatives/*/RESULT.json'))
    positive_paths=[x for x in run_paths if load(x).get('arm',{}).get('id')=='strategic_autonomous_onboarding' and load(x).get('world') in {w['id'] for w in p['worlds'] if w['qualification_region']}]
    if positive_paths:
        positive_paths.sort(key=lambda x:(load(x)['ledger']['summary']['profit'],str(x)))
